import functools
import random
import time


class RetryError(Exception):
    """Raised when every attempt failed; the last failure is the __cause__."""


def retry(attempts=3, base_delay=0.1, factor=2.0, max_delay=30.0,
          exceptions=(Exception,), jitter=True, sleep=time.sleep):
    """Re-run the wrapped function until it returns or the attempts run out.

    Delay before attempt n (1-indexed) is base_delay * factor ** (n - 1),
    capped at max_delay. With jitter on, each delay is scaled by a random
    factor in [0.5, 1.0) so that concurrent callers do not retry in lockstep.
    """
    if attempts < 1:
        raise ValueError(f"attempts must be at least 1, got {attempts}")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            last_exc = None
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    if attempt == attempts:
                        break
                    wait = min(delay, max_delay)
                    if jitter:
                        wait *= random.uniform(0.5, 1.0)
                    sleep(wait)
                    delay *= factor
            raise RetryError(
                f"{func.__name__} failed after {attempts} attempts"
            ) from last_exc

        return wrapper

    return decorator
